"""
Writes the wiki page Performance-History.md into the folder of a machine in the checkout of the performance-history branch from the results of benchmarks/history.py.

    python3 benchmarks/history_page.py [--results PATH] [--out PATH/Performance-History.md]

--results is the folder of one machine (areldir/ on the performance-history branch: machine.json, r00-original.json for the baseline, tags/ and
commits/ from history_commits.py --tags). The page starts with the machine definition (CPU, GPU, OS and version, RAM, VRAM, renderer), then has
one table per benchmark: the baseline (the original Blitz3D) at the top, then one row per version tag, oldest first, each with the change
against the baseline.
"""
import argparse
import datetime
import json
import math
import statistics
import os
import re
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
RESULTS = os.environ.get("PERF_HISTORY", os.path.join(os.path.dirname(ROOT), "performance-history"))  # a checkout of the performance-history branch
PR_URL = "https://github.com/Xaymar/BlitzLLVM/pull/%d"

# The three categories of the page and their tables: (category, title, benchmark, [(key, column, unit)]). A key "bench/metric" names its own benchmark.
TABLES = [
    ("Real World Applications", "Stranded II (map Survival Guide, 640x480, 300 frames)", "stranded2",
     [("ms_avg", "Per frame", "ms")]),
    ("Benchmarks", "Emitted code (`emitted.bb`)", "emitted",
     [("int_loop_ms", "Integer loop", "ms"), ("float_loop_ms", "Float loop", "ms"), ("math_ms", "`Sin` `Cos` `Sqr` `Floor`", "ms"),
      ("array1_ms", "1D array", "ms"), ("array2_ms", "2D array", "ms"), ("types_ms", "Type list walk", "ms"), ("new_delete_ms", "`New` `Delete`", "ms"),
      ("strings_ms", "Strings", "ms"), ("calls_ms", "Calls", "ms"), ("bank_ms", "Banks", "ms"), ("select_ms", "`Select`", "ms")]),
    ("Benchmarks", "Scene: fly-through, waterfall, dungeon (320x180, per frame)", "flythrough",
     [("flythrough/ms_avg", "Fly-through 5000 objects", "ms"), ("waterfall/ms_avg", "Waterfall 2000 sprites", "ms"),
      ("dungeon/ms_avg", "Dungeon 16 rooms", "ms")]),
    ("Benchmarks", "Many lights (`many_lights.bb`, 5000 cubes, 640x360, per frame)", "lights",
     [("8_lights_ms", "8 lights", "ms"), ("32_lights_ms", "32 lights", "ms"), ("127_lights_ms", "127 lights", "ms"),
      ("127_lights_one_moving_ms", "127 lights, one moving", "ms")]),
    ("Benchmarks", "Loading 32 textures of 256x256 (`loading.bb`)", "loading",
     [("blocking_load_ms", "Blocking", "ms"), ("async_load_ms", "`AsyncLoading`, call returns", "ms")]),
    ("Benchmarks", "Movies (`movies.bb`)", "movies", [("cpu_ms", "CPU time of a 5 s 320x240 H.264 movie", "ms")]),
    ("Benchmarks", "Audio (`audio.bb`)", "audio", [("load_ms", "Load 64 sounds", "ms"), ("cpu_ms", "CPU time, 32 channels, 3 s", "ms")]),
    ("Benchmarks", "GPU time of the waterfall passes (per frame)", "gpu", [("gpu_scene_ms", "Scene pass", "ms"), ("gpu_frame_ms", "Whole frame", "ms")]),
    ("Compile time", "Compiling and size of the program", "compile",
     [("hello_compile_ms", "Hello world", "ms"), ("flythrough_compile_ms", "3D program", "ms"), ("stranded2_compile_ms", "Stranded II (about 40,000 lines)", "ms"),
      ("hello_size_kb", "Hello world size", "KB"), ("flythrough_size_kb", "3D program size", "KB"), ("stranded2_size_kb", "Stranded II size", "KB")]),
]
CATEGORIES = ["Real World Applications", "Benchmarks", "Compile time"]


def git_date(rev):
    if not rev:
        return ""
    r = subprocess.run(["git", "log", "-1", "--format=%as", rev], cwd=ROOT, capture_output=True, text=True)
    return r.stdout.strip()


def fmt(v, unit):
    if unit == "KB":
        return "%.2f MB" % (v / 1024) if v >= 1024 else "%.0f KB" % v
    if unit == "ms":
        if v >= 1000:
            return "%.2f s" % (v / 1000)
        return ("%.1f ms" % v) if v >= 100 else ("%.2f ms" % v)
    return "%.0f" % v if abs(v) >= 100 else "%.1f" % v


def quantile(values, q):
    values = sorted(values)
    position = (len(values) - 1) * q
    low = int(position)
    high = min(low + 1, len(values) - 1)
    return values[low] + (values[high] - values[low]) * (position - low)


def stats(m):
    """Mean and standard deviation of the runs of a number."""
    runs = m["runs"]
    return {"mean": statistics.fmean(runs), "spread": statistics.stdev(runs) if len(runs) > 1 else 0.0, "runs": runs}


def mann_whitney_p(a, b):
    """Two-sided p of the Mann-Whitney U test (normal approximation with the correction for ties and for continuity)."""
    n1, n2 = len(a), len(b)
    pooled = sorted([(v, 0) for v in a] + [(v, 1) for v in b])
    ranks = [0.0] * len(pooled)
    ties = 0.0
    i = 0
    while i < len(pooled):
        j = i
        while j + 1 < len(pooled) and pooled[j + 1][0] == pooled[i][0]:
            j += 1
        for k in range(i, j + 1):
            ranks[k] = (i + j) / 2 + 1
        t = j - i + 1
        ties += t ** 3 - t
        i = j + 1
    r1 = sum(r for r, (_, group) in zip(ranks, pooled) if group == 0)
    u1 = r1 - n1 * (n1 + 1) / 2
    mean = n1 * n2 / 2
    n = n1 + n2
    variance = n1 * n2 / 12 * ((n + 1) - ties / (n * (n - 1)))
    if variance <= 0:
        return 1.0
    z = (abs(u1 - mean) - 0.5) / math.sqrt(variance)
    return math.erfc(max(z, 0) / math.sqrt(2))


def verdict(prev, cur, kind):
    """The change of the mean in percent against the baseline (the first row with a number), and the symbol: 📈 better, 📉 worse, ➖ the same. A change counts when it is at
    least 3% and larger than two standard deviations of the difference of the two rows."""
    if prev["mean"] == 0:
        return None, ""
    pct = (cur["mean"] - prev["mean"]) / prev["mean"] * 100
    noise = math.hypot(prev["spread"], cur["spread"])
    significant = abs(pct) >= 3 and abs(cur["mean"] - prev["mean"]) > 2 * noise
    if not significant:
        return pct, "➖"
    return pct, ("📈" if pct < 0 else "📉")


def lookup(results, bench, key):
    if "/" in key:
        bench, key = key.split("/", 1)
    b = results.get("benchmarks", {}).get(bench)
    if not b:
        return None, "not run"
    if "error" in b:
        return None, b["error"]
    m = b.get(key)
    if isinstance(m, dict) and "value" in m:
        return m, ""
    if isinstance(m, dict) and "error" in m:
        return None, m["error"]
    return None, "not run"


def short_reason(text):
    text = " ".join(text.split())
    for needle, reason in (("Unable to load Image sys", "the game can not load its files (backslash paths) in this build"), ("The movie could not be opened", "this build can not play movies"),("Unknown option --profile", "this build has no `--profile`"), ("Microseconds", "needs a newer compiler"),
                           ("no sound loaded", "the original plays no sound here"), ("DirectShow", "the original plays movies with DirectShow, which does not run under Wine"),
                           ("this build reports no GPU time", "this build reports no GPU time"), ("no GPU timers", "the original has no GPU timers")):
        if needle in text:
            return reason
    return text[:90]


def metric_table(revs, machine_results, bench, metrics, only_changes=False):
    """Rows of (revision, [cell per metric]) for the revisions that have at least one number, and the count of revisions without any."""
    rows = []
    prev = {}
    missing = 0
    for rev in revs:
        res = machine_results.get(rev["label"])
        if res is None:
            continue
        cells = []
        for key, column, unit in metrics:
            m, why = lookup(res, bench, key)
            if m is None or (unit == "" and m["runs"] and max(m["runs"]) == 0):
                cells.append("n/a")
                continue
            st = stats(m)
            cell = "**%s**" % fmt(st["mean"], unit)
            if st["spread"] > 0:
                cell += " ±%s" % fmt(st["spread"], unit).replace(" ms", "").replace(" KB", "").replace(" MB", "").replace(" s", "")
            if key in prev:
                pct, sym = verdict(prev[key], st, "lower")
                if pct is not None:
                    cell += "<br>%+.1f%% %s" % (pct, sym)
            cells.append(cell)
            prev.setdefault(key, st)  # the change is against the baseline, the first row with a number
        if all(c == "n/a" for c in cells):
            missing += 1
            continue
        if only_changes and rows and not any("📈" in c or "📉" in c for c in cells):
            continue
        rows.append((rev, cells))
    return rows, missing


RELEASE_URL = "https://github.com/Xaymar/BlitzLLVM/releases/tag/%s"
COMMIT_URL = "https://github.com/Xaymar/BlitzLLVM/commit/%s"


def render_tags(results_dir, out):
    """The page with one row per version tag (X.Y.Z): the release notes say what changed, so the rows only link to them. Needs tags/<tag>.json (history_commits.py --tags)."""
    tags_dir = os.path.join(results_dir, "tags")
    tags = [json.load(open(os.path.join(tags_dir, n))) for n in os.listdir(tags_dir)] if os.path.isdir(tags_dir) else []

    def version(t):
        return tuple(int(x) for x in re.findall(r"\d+", t["tag"]))
    tags.sort(key=version)
    revs, results, no_numbers = [], {}, []
    base = os.path.join(results_dir, "r00-original.json")
    if os.path.isfile(base):  # the baseline: the original Blitz3D, always the top row
        revs.append({"label": "baseline", "rev": "", "prs": [], "tag": ""})
        results["baseline"] = dict(json.load(open(base)), date="")
    for t in tags:
        path = os.path.join(results_dir, "commits", t["state"] + ".json")
        r = json.load(open(path)) if os.path.isfile(path) else None
        if not r or "benchmarks" not in r:
            no_numbers.append(t["tag"])  # builds that do not compile or run are not shown
            continue
        revs.append({"label": t["tag"], "rev": t["commit"], "prs": [], "tag": t["tag"]})
        results[t["tag"]] = dict(r, date=t["date"])
    text = [
        "# Performance History",
        "",
        "The original Blitz3D is the baseline at the top, then one row per version tag of BlitzLLVM, built and benchmarked on its own with the short benchmark set (`benchmarks/history_commits.py --tags`, 3 runs, "
        "mean ± standard deviation). What changed in a version is in its release notes. 📈 is better, 📉 is worse and ➖ is the same as the baseline "
        "(a change under 3%%, or one under two standard deviations of the difference, counts as the same). Last updated %s." % datetime.date.today().isoformat(),
        "",
    ]
    mpath = os.path.join(results_dir, "machine.json")
    if os.path.isfile(mpath):
        m = json.load(open(mpath))
        text += ["## Machine", "", "| | |", "| --- | --- |", "| CPU | %s, %s threads |" % (m["cpu"], m["threads"]), "| GPU | %s |" % m["gpu"],
                 "| OS and version | %s |" % m["os"], "| RAM | %s |" % m["ram"], "| VRAM | %s |" % m["vram"],
                 "| Renderer / converter | %s |" % m["renderer"], "",
                 "Numbers of different machine definitions can not be compared. Every program runs windowed, one after the other, with nothing else running.", ""]
    if no_numbers:
        text += ["Left out because the build does not run: %s." % ", ".join(no_numbers), ""]
    for category in CATEGORIES:
        for cat, title, bench, metrics in TABLES:
            if cat != category:
                continue
            rows, _ = metric_table(revs, results, bench, metrics)
            if not rows:
                continue
            text += ["## %s: %s" % (category, title), "",
                     "| Version | " + " | ".join(c + (" (%s)" % u if u else "") for _, c, u in metrics) + " |",
                     "| --- | " + " | ".join("---:" for _ in metrics) + " |"]
            for rev, cells in rows:
                if not rev["tag"]:
                    text.append("| Baseline: original Blitz3D 1.118 | %s |" % " | ".join(cells))
                    continue
                text.append("| [%s](%s)<br>%s<br>[`%s`](%s) | %s |" % (rev["tag"], RELEASE_URL % rev["tag"], results[rev["label"]]["date"], rev["rev"][:8],
                                                                    COMMIT_URL % rev["rev"], " | ".join(cells)))
            text.append("")
    if not revs:
        text += ["No version has a result yet.", ""]
    open(out, "w").write("<!-- AUTOGENERATED COPYRIGHT HEADER START -->\n<!-- Copyright (C) 2026 Claude <noreply@anthropic.com> -->\n"
                         "<!-- AUTOGENERATED COPYRIGHT HEADER END -->\n" + "\n".join(text))


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--results", default=RESULTS)
    parser.add_argument("--out", default=os.path.join(RESULTS, "Performance-History.md"))
    args = parser.parse_args()
    render_tags(args.results, args.out)


if __name__ == "__main__":
    main()
